<?php
/* ============================================================
   PAINEL DE PORTA — Salas de Treinamento · Redentor Hub
   Monitor vertical na porta da sala (sem login, só leitura)
   Uso: painel_sala.php?sala=joao&k=SUA_CHAVE
        painel_sala.php?sala=angelo&k=SUA_CHAVE
   (a chave real fica em cron_secrets.php, fora do controle de versão)
   ============================================================ */
$__cronsec = @include __DIR__.'/cron_secrets.php';
$CHAVE = $__cronsec['painel_sala'] ?? '';
/* Agendamento de Salas migrou pro piloto em Python (VPS/EasyPanel) — este
   painel de porta agora busca os agendamentos de lá em vez do banco MySQL
   antigo. A ligação crossed de IDs que existia antes (legado) não existe
   mais: 'joao' é sempre a Sala João Gulin, sem inversão. */
const SALAS_API = 'https://redentor-red.5o1fz1.easypanel.host/api/salas/agendamentos';
$SALAS = array(
  'joao'   => array('nome'=>'Sala João Gulin',   'cor'=>'#f97316', 'corSoft'=>'rgba(249,115,22,.14)'),
  'angelo' => array('nome'=>'Sala Angelo Gulin', 'cor'=>'#22c55e', 'corSoft'=>'rgba(34,197,94,.14)')
);
$k = isset($_GET['k']) ? $_GET['k'] : '';
$sala = isset($_GET['sala']) ? strtolower(trim($_GET['sala'])) : '';
if($CHAVE === '' || !hash_equals($CHAVE, $k) || !isset($SALAS[$sala])){ http_response_code(403); die('Acesso negado.'); }

if(isset($_GET['json'])){
  header('Content-Type: application/json; charset=utf-8');
  $hoje = date('Y-m-d');
  $out = array('ok'=>true, 'sala'=>$sala, 'hoje'=>$hoje, 'agora'=>date('H:i'), 'eventos'=>array());
  $ch = curl_init(SALAS_API);
  curl_setopt_array($ch, array(CURLOPT_RETURNTRANSFER=>true, CURLOPT_TIMEOUT=>6, CURLOPT_CONNECTTIMEOUT=>4));
  $resp = curl_exec($ch);
  $falhouCurl = ($resp === false) ? curl_error($ch) : null;
  curl_close($ch);
  if($falhouCurl !== null){
    $out['ok'] = false; $out['erro'] = 'Sem conexão com o serviço de salas: '.$falhouCurl;
  } else {
    $arr = json_decode($resp, true);
    if(is_array($arr)){
      foreach($arr as $r){
        if(!is_array($r)) continue;
        if((isset($r['sala_id'])?$r['sala_id']:'') !== $sala) continue;
        if((isset($r['data'])?$r['data']:'') !== $hoje) continue;
        $out['eventos'][] = array(
          'evento' => isset($r['evento']) ? $r['evento'] : 'Reserva',
          'inicio' => isset($r['inicio']) ? $r['inicio'] : '',
          'fim' => isset($r['fim']) ? $r['fim'] : '',
          'responsavel' => isset($r['responsavel']) ? $r['responsavel'] : ''
        );
      }
      usort($out['eventos'], function($a,$b){ return strcmp($a['inicio'],$b['inicio']); });
    } else {
      $out['ok'] = false; $out['erro'] = 'Resposta inválida do serviço de salas.';
    }
  }
  echo json_encode($out, JSON_UNESCAPED_UNICODE);
  exit;
}
$S = $SALAS[$sala];
?>
<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title><?php echo htmlspecialchars($S['nome']); ?> — Painel</title>
<style>
:root{ --cor:<?php echo $S['cor']; ?>; --corSoft:<?php echo $S['corSoft']; ?>;
  --bg:#ffffff; --panel:#ffffff; --panel2:#f2f4fb; --border:#e3e7f3;
  --navy:#2b3990; --navy2:#1e2a6e; --gold:#c9962e;
  --tx:#1c2452; --tx2:#4a5480; --muted:#8b93b3; }
*{margin:0;padding:0;box-sizing:border-box;}
html,body{height:100%;}
body{background:var(--bg);color:var(--tx);font-family:system-ui,'Segoe UI',Roboto,sans-serif;
  cursor:none;overflow:hidden;display:flex;flex-direction:column;padding:4vmin 4vmin 3vmin;
  -webkit-font-smoothing:antialiased;}
.topo{display:flex;align-items:flex-start;gap:2vmin;}
.dot{width:3.2vmin;height:3.2vmin;border-radius:50%;background:var(--cor);box-shadow:0 0 2.4vmin var(--corSoft);margin-top:.9vmin;}
.snome{font-size:4.4vmin;font-weight:800;letter-spacing:.01em;color:var(--navy2);flex:1;}
.logo{height:9vmin;margin-left:auto;}
.relogio{margin:2.6vmin 0 .5vmin;font-size:14vmin;font-weight:800;letter-spacing:-.02em;line-height:1;font-variant-numeric:tabular-nums;color:var(--navy);}
.relogio .seg{font-size:6.5vmin;color:var(--gold);font-weight:750;}
.data{font-size:3.1vmin;color:var(--tx2);text-transform:capitalize;margin-bottom:3.6vmin;}
.selo{display:inline-flex;align-items:center;gap:1.2vmin;font-size:2.6vmin;font-weight:700;
  padding:1.2vmin 2.4vmin;border-radius:99px;margin-bottom:3.2vmin;}
.selo.livre{background:rgba(34,197,94,.12);color:#15803d;border:1px solid rgba(34,197,94,.4);}
.selo.ocupada{background:rgba(239,68,68,.1);color:#dc2626;border:1px solid rgba(239,68,68,.35);}
.bloco{background:var(--panel);border:1px solid var(--border);border-left:.9vmin solid var(--cor);
  border-radius:2.2vmin;padding:3vmin;margin-bottom:2.6vmin;box-shadow:0 .8vmin 2.6vmin rgba(30,42,110,.07);}
.bloco .tag{font-size:2.1vmin;font-weight:800;letter-spacing:.14em;color:var(--cor);margin-bottom:1.4vmin;}
.bloco h2{font-size:4.2vmin;font-weight:750;line-height:1.15;margin-bottom:1.2vmin;color:var(--navy2);}
.bloco .hor{font-size:3vmin;color:var(--tx2);font-variant-numeric:tabular-nums;}
.bloco .resp{font-size:2.6vmin;color:var(--muted);margin-top:1vmin;}
.prog{height:1.1vmin;background:var(--panel2);border-radius:99px;margin-top:2.2vmin;overflow:hidden;}
.prog i{display:block;height:100%;background:var(--cor);border-radius:99px;transition:width 30s linear;}
.resta{font-size:2.3vmin;color:var(--muted);margin-top:1vmin;}
.lista{flex:1;overflow:hidden;}
.lst-t{font-size:2.2vmin;font-weight:800;letter-spacing:.14em;color:var(--gold);margin:1vmin 0 1.6vmin;}
.it{display:flex;gap:2.2vmin;align-items:center;padding:1.8vmin 0;border-bottom:1px solid var(--border);}
.it .h{font-size:2.8vmin;font-weight:700;font-variant-numeric:tabular-nums;color:var(--navy);min-width:20vmin;}
.it .n{font-size:2.8vmin;font-weight:600;flex:1;color:var(--tx);}
.it .r{font-size:2.2vmin;color:var(--muted);}
.it.pass{opacity:.38;}
.it.pass .n{text-decoration:line-through;}
.livrao{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2.4vmin;}
.livrao .ck{width:16vmin;height:16vmin;border-radius:50%;background:rgba(34,197,94,.08);
  border:.5vmin solid #22c55e;display:flex;align-items:center;justify-content:center;}
.livrao .ck svg{width:8vmin;height:8vmin;stroke:#16a34a;stroke-width:2.4;fill:none;stroke-linecap:round;stroke-linejoin:round;}
.livrao b{font-size:4.4vmin;color:var(--navy2);}
.livrao span{font-size:2.7vmin;color:var(--tx2);}
.rodape{display:flex;justify-content:space-between;align-items:center;font-size:2vmin;color:var(--muted);
  padding-top:2.4vmin;border-top:1px solid var(--border);}
.pulse{display:inline-block;width:1.4vmin;height:1.4vmin;border-radius:50%;background:#22c55e;
  animation:pu 2.2s infinite;vertical-align:middle;margin-right:1vmin;}
@keyframes pu{0%,100%{opacity:1;}50%{opacity:.25;}}
</style>
</head>
<body>
  <div class="topo"><div class="dot"></div><div class="snome"><?php echo htmlspecialchars($S['nome']); ?></div><img class="logo" alt="Auto Viação Redentor" src="data:image/png;base64,"></div>
  <div class="relogio" id="rel">--:--</div>
  <div class="data" id="dta"></div>
  <div id="conteudo"></div>
  <div class="rodape">
    <span><span class="pulse"></span><span id="upd">Atualiza sozinho</span></span>
    <span>Redentor Hub · Auto Viação Redentor</span>
  </div>
<script>
var URLJSON = location.pathname + location.search + '&json=1';
var EVS = [], HOJE = '';
function esc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function hm(){ var n=new Date(); function p(x){return ('0'+x).slice(-2);} return p(n.getHours())+':'+p(n.getMinutes()); }
function relogio(){
  var n=new Date(); function p(x){return ('0'+x).slice(-2);}
  document.getElementById('rel').innerHTML = p(n.getHours())+':'+p(n.getMinutes())+'<span class="seg">:'+p(n.getSeconds())+'</span>';
  var d = n.toLocaleDateString('pt-BR',{weekday:'long', day:'2-digit', month:'long'});
  document.getElementById('dta').textContent = d.charAt(0).toUpperCase()+d.slice(1);
}
function minutos(h){ if(!h)return null; var p=h.split(':'); return parseInt(p[0],10)*60+parseInt(p[1],10); }
function render(){
  var agora = minutos(hm());
  var atual=null, prox=null, futuros=[], passados=[];
  EVS.forEach(function(e){
    var i=minutos(e.inicio), f=minutos(e.fim||e.inicio);
    if(i==null) return;
    if(f!=null && agora>=i && agora<f){ atual=e; }
    else if(agora < i){ futuros.push(e); }
    else passados.push(e);
  });
  if(futuros.length) prox=futuros[0];
  var h='';
  if(atual){
    var i=minutos(atual.inicio), f=minutos(atual.fim||atual.inicio), pc=f>i?Math.min(100,Math.round((agora-i)/(f-i)*100)):100;
    var resta=f-agora;
    h+='<div class="selo ocupada">&#9679; EM USO AGORA</div>';
    h+='<div class="bloco"><div class="tag">EM ANDAMENTO</div><h2>'+esc(atual.evento)+'</h2>'+
       '<div class="hor">'+esc(atual.inicio)+' &ndash; '+esc(atual.fim)+'</div>'+
       (atual.responsavel?'<div class="resp">&#128100; '+esc(atual.responsavel)+'</div>':'')+
       '<div class="prog"><i style="width:'+pc+'%"></i></div>'+
       '<div class="resta">Termina em '+(resta>=60?Math.floor(resta/60)+'h '+(resta%60)+'min':resta+' min')+'</div></div>';
  } else {
    h+='<div class="selo livre">&#10004; SALA LIVRE'+(prox?' AGORA':'')+'</div>';
  }
  if(prox){
    var falta=minutos(prox.inicio)-agora;
    h+='<div class="bloco" style="border-left-color:var(--muted)"><div class="tag" style="color:var(--tx2)">A SEGUIR</div><h2 style="font-size:3.4vmin">'+esc(prox.evento)+'</h2>'+
       '<div class="hor">'+esc(prox.inicio)+' &ndash; '+esc(prox.fim)+
       ' &nbsp;&middot;&nbsp; come\u00e7a em '+(falta>=60?Math.floor(falta/60)+'h '+(falta%60)+'min':falta+' min')+'</div>'+
       (prox.responsavel?'<div class="resp">&#128100; '+esc(prox.responsavel)+'</div>':'')+'</div>';
  }
  if(!EVS.length){
    h+='<div class="livrao"><div class="ck"><svg viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"/></svg></div>'+
       '<b>Livre o dia todo</b><span>Nenhuma reserva para hoje &mdash; agende pelo Redentor Hub</span></div>';
  } else {
    var rest = futuros.slice(prox?1:0);
    if(rest.length || passados.length){
      h+='<div class="lista"><div class="lst-t">AGENDA DE HOJE</div>';
      passados.forEach(function(e){ h+='<div class="it pass"><div class="h">'+esc(e.inicio)+'&ndash;'+esc(e.fim)+'</div><div class="n">'+esc(e.evento)+'</div><div class="r">'+esc(e.responsavel||'')+'</div></div>'; });
      rest.forEach(function(e){ h+='<div class="it"><div class="h">'+esc(e.inicio)+'&ndash;'+esc(e.fim)+'</div><div class="n">'+esc(e.evento)+'</div><div class="r">'+esc(e.responsavel||'')+'</div></div>'; });
      h+='</div>';
    }
  }
  document.getElementById('conteudo').innerHTML=h;
}
async function carregar(){
  try{
    var r=await fetch(URLJSON, {cache:'no-store'});
    var d=await r.json();
    if(d && d.ok){ EVS=d.eventos||[]; HOJE=d.hoje||'';
      var up=document.getElementById('upd'); if(up){ var n=new Date(); function p2(x){return('0'+x).slice(-2);} up.textContent='Atualizado \u00e0s '+p2(n.getHours())+':'+p2(n.getMinutes())+':'+p2(n.getSeconds()); } }
  }catch(e){}
  render();
}
relogio(); setInterval(relogio, 1000);
carregar(); setInterval(carregar, 20000);
setInterval(render, 60000);
/* mantém a tela acesa quando suportado */
(async function(){ try{ if(navigator.wakeLock) await navigator.wakeLock.request('screen'); }catch(e){} })();
document.addEventListener('visibilitychange', function(){ if(!document.hidden){ carregar(); (async function(){ try{ if(navigator.wakeLock) await navigator.wakeLock.request('screen'); }catch(e){} })(); } });
</script>
</body>
</html>
